                unsupported += 1; unsupportedMask[i / 4] = 1; bytes[i+3] = 255
            } else if bytes[i+3] != 255 { throw StudyError.invalidComputeOutput }
        }
        return .init(width: width, height: height, rgba: Data(bytes), unsupportedPixels: unsupported,
                     unsupportedPixelMask: Data(unsupportedMask))
    }
}

/// Optional GPU backend input, generated from the same validated source samples,
/// camera, and display transform as the CPU oracle. Every row is a 16-byte float4.
/// Parameters: 0 origin/halfW, 1 forward/halfH, 2 right/radius, 3 up/panelHalfExtent,
/// 4 Bradford ratio/exposure, 5 sample count/area count/minimum depth/grid count.
/// Sample color.w is zero for a point/directional source or a one-based area index.
public struct StudyComputeInput: Sendable {
    public let width: Int
    public let height: Int
    public let parameters: [SIMD4<Float>]
    public let samples: [SIMD4<Float>]
    public let areas: [SIMD4<Float>]

    public init(scene: LightingScene, width: Int = 192) throws {
        let setup = try StudySetup(scene: scene, width: width, quality: .interactive)
        let c = vec(setup.geometry.center), camera = setup.camera
        let origin = vec(camera.position) - c
        let samples = setup.lighting.computeSamples(relativeTo: c)
        let areas = setup.lighting.computeAreas(relativeTo: c)
        self.width = width; self.height = setup.height
        self.samples = samples; self.areas = areas
        parameters = [pack(origin, setup.halfW), pack(vec(camera.forward), setup.halfH),
                      pack(vec(camera.right), setup.geometry.radius), pack(vec(camera.up), setup.geometry.panelHalfExtent),
                      setup.transform.computeParameters,
                      .init(Float(samples.count / 3), Float(areas.count / 3), Float(CameraFraming.minimumDepthMeters), 8)]
    }
}

private struct StudySetup {
    let camera: CameraFraming
    let geometry: StudyGeometry
    let lighting: StudyLighting
    let transform: PreviewColorTransform
    let height: Int
    let halfW: Double
    let halfH: Double

    init(scene: LightingScene, width: Int, quality: StudyQuality) throws {
        let maximum = quality == .reference ? 96 : 192
        guard width >= 24, width <= maximum, width.isMultiple(of: 3) else { throw StudyError.invalidResolution }
        guard let camera = CameraFraming(scene: scene), let geometry = StudyGeometry(center: scene.subject),
              camera.position.y > geometry.panelY + 0.01,
              camera.subjectDistanceMeters > geometry.radius + CameraFraming.minimumDepthMeters else { throw StudyError.invalidCamera }
        let light = try StudyLighting(scene: scene, quality: quality)
        guard let transform = PreviewColorTransform(settings: scene.effectivePreviewSettings) else { throw StudyError.invalidScene }
        self.camera = camera; self.geometry = geometry; lighting = light; self.transform = transform
        height = width * 2 / 3
        halfW = CameraLens.sensorWidthMillimeters / (2 * camera.lens.focalLengthMillimeters)
        halfH = CameraLens.sensorHeightMillimeters / (2 * camera.lens.focalLengthMillimeters)
    }
}

/// Shared cooperative work bound for the two deterministic CPU renderers.
struct StudyPixelCancellation {
    private var pixelsUntilCheck = 0

    /// Call before each pixel, including background/unsupported pixels. A
    /// close-up with many area lights can make a whole scanline expensive;
    /// bound cooperative work between checks without changing pixel sampling.
    @inline(__always)
    mutating func check(_ isCancelled: () -> Bool) throws {
        if pixelsUntilCheck == 0 {
            guard !isCancelled() else { throw StudyError.cancelled }
            pixelsUntilCheck = 8
        }
        pixelsUntilCheck -= 1
    }
}

/// Deterministic CPU oracle/diagnostic preview. Direct light only; deliberately small
/// bounded images. Not a real-time production GPU renderer or photographic ground truth.
public enum ReferenceStudyRenderer {
    public static func render(scene: LightingScene, width: Int = 120, quality: StudyQuality = .interactive,
                              isCancelled: () -> Bool = { false }) throws -> StudyImage {
        let setup = try StudySetup(scene: scene, width: width, quality: quality)
        let camera = setup.camera, geometry = setup.geometry, light = setup.lighting, transform = setup.transform
        let height = setup.height, origin = vec(camera.position)
        let forward = vec(camera.forward), right = vec(camera.right), up = vec(camera.up)
        let halfW = setup.halfW, halfH = setup.halfH
        var pixels = [UInt8](repeating: 255, count: width * height * 4)
        var unsupportedMask = [UInt8](repeating: 0, count: width * height)
        var unsupported = 0
        var cancellation = StudyPixelCancellation()
        let sphere: StudyMaterial = .dielectric(reflectance: 0.18, roughness: 0.32, f0: 0.04)
        let panel: StudyMaterial = .diffuse(reflectance: 0.30)
        for y in 0..<height {
            let py = (1 - 2 * (Double(y) + 0.5) / Double(height)) * halfH
            for x in 0..<width {
                try cancellation.check(isCancelled)
                let px = (2 * (Double(x) + 0.5) / Double(width) - 1) * halfW
                guard let ray = normalized3(forward + right * px + up * py) else { throw StudyError.invalidCamera }
                let minT = CameraFraming.minimumDepthMeters / dot3(ray, forward)
                let sphereT = geometry.sphereHit(origin: origin, direction: ray, minimum: minT)
                var planeT: Double?
                if ray.y < -1e-12 {
                    let t = (geometry.panelY - origin.y) / ray.y
                    if t >= minT, geometry.inPanel(origin + ray * t) { planeT = t }
                }
                let index = 4 * (y * width + x)
                var p: SIMD3<Double>, n: SIMD3<Double>, material: StudyMaterial
                if let t = sphereT, t < (planeT ?? .infinity) {
                    p = origin + ray * t
                    guard let unit = normalized3(p - vec(geometry.center)) else { throw StudyError.invalidSurface }
                    n = unit; material = sphere
                } else if let t = planeT {
                    p = origin + ray * t; n = .init(0, 1, 0); material = panel
                } else {
                    pixels[index] = 18; pixels[index + 1] = 20; pixels[index + 2] = 24
                    continue
                }
                do {
                    let signal = try light.evaluate(receiver: p, normal: n, view: -ray, material: material, geometry: geometry)
                    guard let color = transform.display(signal.signalXYZ) else { throw StudyError.invalidSurface }
                    pixels[index] = byte(color.red); pixels[index + 1] = byte(color.green); pixels[index + 2] = byte(color.blue)
                } catch StudyError.invalidSurface {
                    unsupported += 1
                    unsupportedMask[index / 4] = 1
                    pixels[index] = 255; pixels[index + 1] = 0; pixels[index + 2] = 255
                }
            }
        }
        if isCancelled() { throw StudyError.cancelled }
        return .init(width: width, height: height, rgba: Data(pixels), unsupportedPixels: unsupported,
                     unsupportedPixelMask: Data(unsupportedMask))
    }

    private static func byte(_ v: Double) -> UInt8 { UInt8((min(1, max(0, v)) * 255).rounded()) }
}

private func vec(_ p: Position) -> SIMD3<Double> { .init(p.x, p.y, p.z) }
private func vec(_ d: UnitDirection) -> SIMD3<Double> { .init(d.x, d.y, d.z) }
private func dot3(_ a: SIMD3<Double>, _ b: SIMD3<Double>) -> Double { a.x * b.x + a.y * b.y + a.z * b.z }
private func normalized3(_ v: SIMD3<Double>) -> SIMD3<Double>? {
    let length = sqrt(dot3(v, v))
    guard length.isFinite, length > 0 else { return nil }
    return v / length
}

private func pack(_ v: SIMD3<Double>, _ w: Double) -> SIMD4<Float> {
    .init(Float(v.x), Float(v.y), Float(v.z), Float(w))
}

/// A bounded, least-recently-used cache for completed Study frames. The owner
/// supplies payload costs; keys and other value storage are bounded by the
/// entry limit and must be kept small independently. Synchronization and render
/// cancellation remain the owner's responsibility.
public struct StudyFrameCache<Key: Equatable & Sendable, Value: Sendable>: Sendable {
    public let maximumCount: Int
    public let maximumPixelBytes: Int
    public let maximumMaskBytes: Int

    public var count: Int { entries.count }
    public private(set) var pixelBytes = 0
    public private(set) var maskBytes = 0

    private struct Entry: Sendable {
        let key: Key
        let value: Value
        let pixelBytes: Int
        let maskBytes: Int
    }

    // Least recently used first. No capacity reservation: a large configured
    // limit does not allocate storage until valid entries are actually added.
    private var entries: [Entry] = []

    /// Limits are immutable and must be positive. Payload costs may be zero;
    /// the entry limit still bounds zero-cost entries.
    public init(maximumCount: Int, maximumPixelBytes: Int, maximumMaskBytes: Int) {
        precondition(maximumCount > 0 && maximumPixelBytes > 0 && maximumMaskBytes > 0,
                     "Study frame cache limits must be positive")
        self.maximumCount = maximumCount
        self.maximumPixelBytes = maximumPixelBytes
        self.maximumMaskBytes = maximumMaskBytes
    }

    /// A hit becomes most recently used. A miss leaves order and costs intact.
    public mutating func value(for key: Key) -> Value? {
        guard let index = entries.firstIndex(where: { $0.key == key }) else { return nil }
        let entry = entries.remove(at: index)
        entries.append(entry)
        return entry.value
    }

    /// Returns false for negative or individually oversized costs, leaving
    /// every existing entry and its recency unchanged. An admitted replacement
    /// removes the old value before evicting other entries and becomes newest.
    /// Eviction precedes append, so neither byte budget nor the entry limit is
    /// transiently exceeded. Separate subtraction checks avoid overflow even
    /// when a configured byte limit is Int.max.
    @discardableResult
    public mutating func insert(_ value: Value, for key: Key,
                                pixelBytes: Int, maskBytes: Int) -> Bool {
        guard pixelBytes >= 0, pixelBytes <= maximumPixelBytes,
              maskBytes >= 0, maskBytes <= maximumMaskBytes else { return false }

        if let index = entries.firstIndex(where: { $0.key == key }) {
            remove(at: index)
        }
        while !entries.isEmpty &&
                (entries.count >= maximumCount ||
                 self.pixelBytes > maximumPixelBytes - pixelBytes ||
                 self.maskBytes > maximumMaskBytes - maskBytes) {
            remove(at: 0)
        }

        entries.append(Entry(key: key, value: value, pixelBytes: pixelBytes, maskBytes: maskBytes))
        self.pixelBytes += pixelBytes
        self.maskBytes += maskBytes
        return true
    }

    /// Selective invalidation, for example after a rendering backend fails.
    /// Surviving entries retain their relative least-recently-used order.
    public mutating func removeAll(where shouldBeRemoved: (Value) -> Bool) {
        for index in entries.indices.reversed() where shouldBeRemoved(entries[index].value) {
            remove(at: index)
        }
    }

    private mutating func remove(at index: Int) {
        let entry = entries.remove(at: index)
        pixelBytes -= entry.pixelBytes
        maskBytes -= entry.maskBytes
    }
}

import Foundation

/// Conservative routing for the optional sphere/panel Float32 backend.
/// This is a numerical-domain decision, not a physical rendering guarantee.
public enum StudyFloat32Eligibility {
    public static let maximumRelativeDistanceMeters = 20.0
    /// An engineering guard band around discontinuous near-field masks. This
    /// is deliberately larger than the observed micrometer-scale drift, but
    /// is not a proved error bound for every GPU or floating-point operation.
    public static let surfaceMarginMeters = 0.001

    public static func supports(_ scene: LightingScene) -> Bool {
        supports(scene, width: 192)
    }

    public static func supports(_ scene: LightingScene, width: Int) -> Bool {
        guard width >= 24, width <= 192, width.isMultiple(of: 3) else { return false }
        guard (try? scene.validated()) != nil,
              let geometry = StudyGeometry(center: scene.subject),
              let camera = CameraFraming(scene: scene),
              camera.position.y > geometry.panelY + 0.01,
              camera.subjectDistanceMeters > geometry.radius + CameraFraming.minimumDepthMeters,
              camera.subjectDistanceMeters <= maximumRelativeDistanceMeters,
              scene.lights.allSatisfy({ $0.candela == 0 || $0.position.distance(to: scene.subject) <= maximumRelativeDistanceMeters }),
              silhouetteShellFitsBudget(geometry: geometry, camera: camera, width: width)
        else { return false }

        let panel = visiblePanelBounds(geometry: geometry, camera: camera)
        let subject = vector(scene.subject)
        for light in scene.lights where light.candela > 0 {
            let source = vector(light.position) - subject
            let optics = light.effectiveOptics
            if optics.kind == .rectangle {
                guard let frame = StudioPhotometry.frame(for: light, subject: scene.subject) else { return false }
                let right = vector(frame.right), up = vector(frame.up)
                let halfWidth = optics.widthMeters / 2, halfHeight = optics.heightMeters / 2
                let guardDistance = max(0.05, max(optics.widthMeters, optics.heightMeters) / 4)

                // The closest point on the emitting face to the sphere center
                // gives a conservative separation from the whole sphere.
                let x = clamp(dot(-source, right), -halfWidth, halfWidth)
                let y = clamp(dot(-source, up), -halfHeight, halfHeight)
                let closest = source + right * x + up * y
                let sphereSeparation = max(0, length(closest) - geometry.radius)
                guard sphereSeparation > guardDistance + surfaceMarginMeters else { return false }

                if let panel {
                    let extents = absolute(right) * halfWidth + absolute(up) * halfHeight
                    guard panel.distance(to: source, halfExtents: extents) > guardDistance + surfaceMarginMeters
                    else { return false }
                }
            } else {
                if optics.kind == .directional,
                   StudioPhotometry.frame(for: light, subject: scene.subject) == nil { return false }
                let sphereSeparation = abs(length(source) - geometry.radius)
                guard sphereSeparation > 0.05 + surfaceMarginMeters else { return false }
                if let panel, panel.distance(to: source, halfExtents: .zero) <= 0.05 + surfaceMarginMeters {
                    return false
                }
            }
        }
        return true
    }

    /// The distance-scaled margin is an engineering allowance for Float32
    /// ray/sphere classification drift, not a proved numerical error bound.
    /// Spending at most 1/510 of the pixels on possible silhouette changes
    /// reserves half an 8-bit channel level of worst-case mean error for them,
    /// leaving budget for other drift without proving total GPU agreement.
    private static func silhouetteShellFitsBudget(geometry: StudyGeometry, camera: CameraFraming, width: Int) -> Bool {
        // EmitterFrame's near-vertical x-axis fallback need not be exactly
        // perpendicular to forward. The radial shell assumes an orthogonal
        // camera basis, so keep that narrow non-axial cone on the CPU. An
        // exactly vertical view still has an orthogonal basis and is allowed.
        guard hypot(camera.forward.x, camera.forward.z) > 1e-12 ||
                (camera.forward.x == 0 && camera.forward.z == 0) else { return false }
        let distance = camera.subjectDistanceMeters
        let margin = 32 * Double(Float.ulpOfOne) * distance
        let innerRadius = max(0, geometry.radius - margin)
        let outerRadius = geometry.radius + margin
        guard outerRadius < distance else { return false }

        // The camera targets the center. For sensor slopes px, py, the
        // tangent circle of radius R satisfies px² + py² = R² / (D² - R²).
        func squaredSlope(_ radius: Double) -> Double {
            let radiusSquared = radius * radius
            return radiusSquared / (distance * distance - radiusSquared)
        }
        let innerSquaredSlope = squaredSlope(innerRadius)
        let outerSquaredSlope = squaredSlope(outerRadius)
        let height = width * 2 / 3
        let pixelBudget = width * height / 510
        let halfWidth = CameraLens.sensorWidthMillimeters / (2 * camera.lens.focalLengthMillimeters)
        let halfHeight = CameraLens.sensorHeightMillimeters / (2 * camera.lens.focalLengthMillimeters)

        func pixelRange(_ lower: Double, _ upper: Double) -> ClosedRange<Int>? {
            // Invert px = (2 * (x + 0.5) / width - 1) * halfWidth.
            // Allow Double roundoff through sqrt and the inverse transform,
            // then round outward to retain centers on an interval edge.
            let indexMargin = 32 * Double.ulpOfOne * Double(width)
            let firstIndex = (Double(width) * (lower / halfWidth + 1) / 2 - 0.5).nextDown
            let lastIndex = (Double(width) * (upper / halfWidth + 1) / 2 - 0.5).nextUp
            let first = max(0, ceil(firstIndex - indexMargin))
            let last = min(Double(width - 1), floor(lastIndex + indexMargin))
            guard first <= last else { return nil }
            return Int(first)...Int(last)
        }

        var potentialPixels = 0
        for y in 0..<height {
            let py = (1 - 2 * (Double(y) + 0.5) / Double(height)) * halfHeight
            let squaredY = py * py
            // Separate Double-roundoff padding keeps a tangent row from
            // disappearing through a tiny negative squared-slope difference.
            let slopeMargin = 32 * Double.ulpOfOne * max(outerSquaredSlope, squaredY)
            let outerSquaredX = outerSquaredSlope - squaredY
            guard outerSquaredX >= -slopeMargin else { continue }
            let outerX = sqrt(max(0, outerSquaredX + slopeMargin))
            let innerX = sqrt(max(0, innerSquaredSlope - squaredY - slopeMargin))
            let negative = pixelRange(-outerX, -innerX)
            let positive = pixelRange(innerX, outerX)
            if let negative {
                potentialPixels += negative.upperBound - negative.lowerBound + 1
            }
            if let positive {
                potentialPixels += positive.upperBound - positive.lowerBound + 1
                if let negative {
                    // When innerX is zero, both intervals can contain the
                    // odd-width center pixel. Count their integer union.
                    let overlapFirst = max(negative.lowerBound, positive.lowerBound)
                    let overlapLast = min(negative.upperBound, positive.upperBound)
                    potentialPixels -= max(0, overlapLast - overlapFirst + 1)
                }
            }
            if potentialPixels > pixelBudget { return false }
        }
        return true
    }

    private struct Bounds {
        let low: SIMD3<Double>
        let high: SIMD3<Double>

        /// AABB separation is a lower bound on actual shape separation. It can
        /// route additional corner/rotated cases to CPU, never prove clearance
        /// from a larger distance than the actual shapes have.
        func distance(to center: SIMD3<Double>, halfExtents: SIMD3<Double>) -> Double {
            var separation = SIMD3<Double>.zero
            for axis in 0..<3 {
                separation[axis] = max(0, max(low[axis] - center[axis] - halfExtents[axis],
                                               center[axis] - halfExtents[axis] - high[axis]))
            }
            return length(separation)
        }
    }

    /// Clip the real finite panel against the camera frustum. Its conservative
    /// AABB avoids rejecting ordinary close-up rigs merely because a source
    /// approaches a distant, invisible part of the panel. Every plane's padding
    /// is scaled by its normal length, so it represents the same meter margin.
    private static func visiblePanelBounds(geometry: StudyGeometry, camera: CameraFraming) -> Bounds? {
        let extent = geometry.panelHalfExtent, y = -geometry.radius
        var polygon: [SIMD3<Double>] = [
            .init(-extent, y, -extent), .init(extent, y, -extent),
            .init(extent, y, extent), .init(-extent, y, extent)
        ]
        let origin = vector(camera.position) - vector(geometry.center)
        let forward = vector(camera.forward), right = vector(camera.right), up = vector(camera.up)
        let halfWidth = CameraLens.sensorWidthMillimeters / (2 * camera.lens.focalLengthMillimeters)
        let halfHeight = CameraLens.sensorHeightMillimeters / (2 * camera.lens.focalLengthMillimeters)
        let planes: [(SIMD3<Double>, Double)] = [
            (forward, CameraFraming.minimumDepthMeters),
            (forward * halfWidth + right, 0), (forward * halfWidth - right, 0),
            (forward * halfHeight + up, 0), (forward * halfHeight - up, 0)
        ]
        for (normal, minimum) in planes {
            guard !polygon.isEmpty else { return nil }
            let padding = surfaceMarginMeters * length(normal)
            func signedDistance(_ point: SIMD3<Double>) -> Double {
                dot(point - origin, normal) - minimum + padding
            }
            var clipped: [SIMD3<Double>] = []
            var previous = polygon.last!
            var previousDistance = signedDistance(previous)
            for current in polygon {
                let currentDistance = signedDistance(current)
                if (previousDistance >= 0) != (currentDistance >= 0) {
                    let t = previousDistance / (previousDistance - currentDistance)
                    clipped.append(previous + (current - previous) * t)
                }
                if currentDistance >= 0 { clipped.append(current) }
                previous = current; previousDistance = currentDistance
            }
            polygon = clipped
        }
        guard let first = polygon.first else { return nil }
        var low = first, high = first
        for point in polygon.dropFirst() {
            for axis in 0..<3 {
                low[axis] = min(low[axis], point[axis])
                high[axis] = max(high[axis], point[axis])
            }
        }
        return Bounds(low: low, high: high)
    }

    private static func vector(_ point: Position) -> SIMD3<Double> { .init(point.x, point.y, point.z) }
    private static func vector(_ direction: UnitDirection) -> SIMD3<Double> { .init(direction.x, direction.y, direction.z) }
    private static func dot(_ a: SIMD3<Double>, _ b: SIMD3<Double>) -> Double { a.x * b.x + a.y * b.y + a.z * b.z }
    private static func length(_ value: SIMD3<Double>) -> Double { sqrt(dot(value, value)) }
    private static func absolute(_ value: SIMD3<Double>) -> SIMD3<Double> { .init(abs(value.x), abs(value.y), abs(value.z)) }
    private static func clamp(_ value: Double, _ low: Double, _ high: Double) -> Double { min(high, max(low, value)) }
}

import Foundation
import XCTest
import LightingCore
@testable import KeyAndFill

final class StudyRenderCacheTests: XCTestCase {
    /// A 24 × 16 CPU render needs at least 48 pixel cancellation checks. A
    /// budget of eight therefore permits a cache hit, but interrupts real CPU
    /// work without timers, artificial renderers or production test counters.
    private final class CancellationBudget: @unchecked Sendable {
        private let lock = NSLock()
        private var checks = 0
        private var cancellationCheck: Int?

        func requested() -> Bool {
            lock.lock()
            defer { lock.unlock() }
            checks += 1
            return cancellationCheck.map { checks >= $0 } ?? false
        }

        func reset(cancelAt check: Int? = nil) {
            lock.lock()
            checks = 0
            cancellationCheck = check
            lock.unlock()
        }

        var checkCount: Int {
            lock.lock()
            defer { lock.unlock() }
            return checks
        }
    }

    private func portraitScene(exposure: Double = 0) -> LightingScene {
        var scene = LightingScene.portrait()
        scene.camera = .init(x: 0, y: 1.6, z: 1.7)
        scene.cameraLens = .init(focalLengthMillimeters: 70)
        scene.previewSettings = .init(exposureStops: exposure)
        return scene
    }

    private func assertCancelled(_ engine: StudyRenderEngine, scene: LightingScene,
                                 width: Int = 24, subject: StudySubject = .bust,
                                 file: StaticString = #filePath, line: UInt = #line) async {
        do {
            _ = try await engine.render(scene: scene, width: width, subject: subject)
            XCTFail("Uncached or cancelled work must not return a frame", file: file, line: line)
        } catch {
            XCTAssertEqual(error as? StudyError, .cancelled, file: file, line: line)
        }
    }

    private func cachedFrame(_ engine: StudyRenderEngine, budget: CancellationBudget,
                             scene: LightingScene, width: Int = 24,
                             subject: StudySubject = .bust) async throws -> StudyRenderedFrame {
        budget.reset(cancelAt: 8)
        defer { budget.reset() }
        return try await engine.render(scene: scene, width: width, subject: subject)
    }

    func testRevertedAndReopenedSceneReusesExactSuccessfulPixels() async throws {
        let budget = CancellationBudget()
        let engine = StudyRenderEngine(cancellationRequested: { budget.requested() })
        let original = portraitScene()
        let first = try await engine.render(scene: original, width: 24, subject: .bust)
        XCTAssertEqual(first.backend, .cpu)
        XCTAssertEqual(first.image, try PortraitStudyRenderer.render(scene: original, width: 24))

        var edited = original
        edited.previewSettings?.exposureStops = 2
        let second = try await engine.render(scene: edited, width: 24, subject: .bust)
        XCTAssertNotEqual(second.image, first.image)

        // Reopening uses a new decoded value, with the persisted light IDs.
        let reopened = try JSONDecoder().decode(LightingScene.self, from: JSONEncoder().encode(original))
        let reused = try await cachedFrame(engine, budget: budget, scene: reopened)
        XCTAssertEqual(reused.image, first.image)
        XCTAssertEqual(reused.backend, first.backend)
    }

    func testEntryLimitEvictsLeastRecentlyUsedSuccessfulFrame() async throws {
        let budget = CancellationBudget()
        let engine = StudyRenderEngine(cancellationRequested: { budget.requested() })
        let original = portraitScene()
        let scenes = (0...StudyRenderEngine.maximumCachedFrames).map { exposure in
            var scene = original
            scene.previewSettings?.exposureStops = Double(exposure)
            return scene
        }
        var frames: [StudyRenderedFrame] = []
        for scene in scenes.dropLast() {
            frames.append(try await engine.render(scene: scene, width: 24, subject: .bust))
        }
        XCTAssertLessThan(frames.reduce(0) { $0 + $1.image.rgba.count },
                          StudyRenderEngine.maximumCachedPixelBytes)
        _ = try await cachedFrame(engine, budget: budget, scene: scenes[0])
        let newest = try await engine.render(scene: scenes.last!, width: 24, subject: .bust)

        // Refreshing the first entry makes the second entry the eviction target.
        budget.reset(cancelAt: 8)
        await assertCancelled(engine, scene: scenes[1])
        let recent = try await cachedFrame(engine, budget: budget, scene: scenes[0])
        let last = try await cachedFrame(engine, budget: budget, scene: scenes.last!)
        XCTAssertEqual(recent.image, frames[0].image)
        XCTAssertEqual(last.image, newest.image)
    }

    func testPixelBudgetEvictsLargeFramesBeforeEntryLimit() async throws {
        let budget = CancellationBudget()
        let engine = StudyRenderEngine(cancellationRequested: { budget.requested() })
        var original = LightingScene.portrait()
        // Deliberately outside Metal's domain, so the cancellation probe tests
        // actual CPU work on devices both with and without a Metal backend.
        original.camera.z = 25
        original.previewSettings = .init()
        let scenes = (0..<3).map { exposure in
            var scene = original
            scene.previewSettings?.exposureStops = Double(exposure)
            return scene
        }
        var frames: [StudyRenderedFrame] = []
        for scene in scenes {
            let frame = try await engine.render(scene: scene, width: 192)
            XCTAssertEqual(frame.backend, .cpu)
            frames.append(frame)
        }
        XCTAssertLessThan(scenes.count, StudyRenderEngine.maximumCachedFrames)
        XCTAssertGreaterThan(frames.reduce(0) { $0 + $1.image.rgba.count },
                             StudyRenderEngine.maximumCachedPixelBytes)
        XCTAssertLessThanOrEqual(frames[1].image.rgba.count + frames[2].image.rgba.count,
                                StudyRenderEngine.maximumCachedPixelBytes)
        budget.reset(cancelAt: 8)
        await assertCancelled(engine, scene: scenes[0], width: 192, subject: .sphere)
        for index in 1...2 {
            let reused = try await cachedFrame(engine, budget: budget, scene: scenes[index],
                                               width: 192, subject: .sphere)
            XCTAssertEqual(reused.image, frames[index].image)
        }
    }

    func testEveryRenderingControlKeepsDistinctCacheIdentity() async throws {
        let budget = CancellationBudget()
        let engine = StudyRenderEngine(cancellationRequested: { budget.requested() })
        var original = portraitScene()
        original.lights[0].optics = .init(kind: .rectangle)
        let first = try await engine.render(scene: original, width: 24, subject: .bust)
        let edits: [(String, (inout LightingScene) -> Void)] = [
            ("subject", { $0.subject.x += 0.1 }),
            ("camera", { $0.camera.y += 0.1 }),
            ("lens", { $0.cameraLens?.focalLengthMillimeters = 85 }),
            ("light position", { $0.lights[0].position.z += 0.2 }),
            ("output", { $0.lights[0].candela = 600 }),
            ("temperature", { $0.lights[0].kelvin = 3200 }),
            ("emitter kind", { $0.lights[0].optics?.kind = .directional }),
            ("emitter aim", { $0.lights[0].optics?.aimTarget = .init(x: 0.2, y: 1.5, z: 0) }),
            ("emitter width", { $0.lights[0].optics?.widthMeters = 0.8 }),
            ("emitter height", { $0.lights[0].optics?.heightMeters = 1.1 }),
            ("emitter roll", { $0.lights[0].optics?.rollDegrees = 30 }),
            ("exposure", { $0.previewSettings?.exposureStops = 1 }),
            ("white balance", { $0.previewSettings?.whiteBalanceKelvin = 4500 }),
            ("light count", { $0.lights.removeLast() }),
            ("light order", { $0.lights.reverse() })
        ]
        for (name, edit) in edits {
            var changed = original
            edit(&changed)
            _ = try changed.validated()
            budget.reset(cancelAt: 8)
            do {
                _ = try await engine.render(scene: changed, width: 24, subject: .bust)
                XCTFail("Changing \(name) must require a new render")
            } catch {
                XCTAssertEqual(error as? StudyError, .cancelled, name)
            }
        }
        let reused = try await cachedFrame(engine, budget: budget, scene: original)
        XCTAssertEqual(reused.image, first.image,
                       "Interrupted edits must leave the completed original available")
    }

    func testSubjectAndResolutionDoNotShareFrames() async throws {
        let budget = CancellationBudget()
        let engine = StudyRenderEngine(cancellationRequested: { budget.requested() })
        let scene = portraitScene()
        _ = try await engine.render(scene: scene, width: 24, subject: .bust)
